"""The anime look: every scene's picture is generated by an image model (free: Cloudflare Workers AI, then Pollinations),
in one locked style, then animated here with camera moves, pop-ups and captions.
If a picture cannot be made, that scene is drawn by the code renderer instead, so a video is never lost."""
import base64
import hashlib
import io
import json
import math
import os
import time
from functools import lru_cache
from pathlib import Path

import requests
from PIL import Image, ImageFilter

ROOT = Path(__file__).resolve().parent.parent
CACHE = ROOT / "output" / "art-cache"
W, H = 1080, 1920

STYLE = ("masterpiece, best quality, high-end anime key visual, manhwa webtoon illustration, detailed cel shading, crisp clean lineart, "
         "rich saturated colors, cinematic lighting, soft painted background with depth, expressive eyes, vertical 9:16 composition, "
         "no text, no letters, no watermark, no speech bubbles")
NEGATIVE = "text, letters, watermark, logo, speech bubble, blurry, low quality, deformed, extra limbs, extra fingers, photo, 3d render"

LOOK_OF = {"cat": "{c} cat with large glossy expressive eyes, soft fur, small pink nose",
           "dog": "{c} dog with big loyal eyes and floppy ears", "cow": "{c} cow with gentle big eyes and a small bell",
           "chicken": "{c} chicken with a bright red comb and proud round body",
           "sun": "a glowing smiling sun with a gentle face and warm rays", "moon": "a calm glowing moon with a sleepy kind face"}
MOOD = {"sleepy": "sleeping peacefully, eyes closed", "happy": "happy and bright-eyed", "angry": "angry with a fierce frown", "scared": "frightened, wide eyes",
        "shocked": "shocked, jaw dropped", "smug": "smug confident grin", "sad": "sad teary eyes", "dizzy": "dizzy swirling eyes", "neutral": "calm expression"}
WORLD = {"dawn": "soft pink and gold dawn light", "day": "bright warm daylight", "dusk": "purple and orange dusk light", "storm": "dramatic stormy sky",
         "night": "deep blue night with a glowing moon and stars", "sunset": "glowing orange sunset"}
STAGE = {"street": "a city street", "park": "a green park", "kitchen": "a cozy kitchen", "shop": "a small shop", "office": "an office",
         "classroom": "a classroom", "home": "a cozy living room with a sofa and a window"}


def _actor_text(script, actor):
    entry = (script.get("cast_src") or {}).get(actor.get("who"), {})
    kind = entry.get("kind")
    if kind:
        col = entry.get("color") or ("orange tabby" if kind == "cat" else "")
        base = LOOK_OF.get(kind, kind).format(c=col or "")
    else:
        base = " ".join(str(entry.get(k, "")) for k in ("age", "gender", "role")).strip() or "a person"
    return f"{base}, {MOOD.get(actor.get('mood'), 'calm expression')}"


def scene_prompt(script, sc):
    """One picture per scene. A writer-supplied 'visual' sentence wins; the character description is repeated word for word in every scene."""
    src = sc.get("_src") or {}
    who = "; ".join(_actor_text(script, a) for a in src.get("actors", []))
    return (f"{STYLE}. {src.get('visual', '')} Character: {who}. Setting: {STAGE.get(src.get('stage'), 'a place')}, "
            f"{WORLD.get(src.get('world'), 'daylight')}. Mood: {sc.get('tone', 'calm')}.")


def _seed(script):
    return int(hashlib.sha1(str(script.get("short_title", script.get("title", ""))).encode()).hexdigest()[:6], 16)


def _decode(r):
    ct = r.headers.get("content-type", "")
    if "json" in ct:
        j = r.json()
        res = j.get("result", j)
        b = res.get("image") if isinstance(res, dict) else None
        if not b:
            raise ValueError(f"no image in reply: {str(j)[:200]}")
        data = base64.b64decode(b)
    else:
        data = r.content
    return Image.open(io.BytesIO(data)).convert("RGB")


def _cloudflare(prompt, seed, negative=NEGATIVE):
    tok, acct = os.environ.get("CLOUDFLARE_API_TOKEN"), os.environ.get("CLOUDFLARE_ACCOUNT_ID")
    if not (tok and acct):
        raise ValueError("no Cloudflare key")
    base = f"https://api.cloudflare.com/client/v4/accounts/{acct}/ai/run/"
    hdr = {"Authorization": f"Bearer {tok}"}
    try:                                                    # portrait size, anime-tuned lightning model first (it takes width and height)
        r = requests.post(base + "@cf/bytedance/stable-diffusion-xl-lightning", headers=hdr, timeout=120,
                          json={"prompt": prompt, "negative_prompt": negative, "width": 768, "height": 1344, "num_steps": 8, "guidance": 1.5, "seed": seed})
        r.raise_for_status()
        return _decode(r)
    except Exception as e:
        print(f"      sdxl-lightning failed ({str(e)[:120]}); trying flux", flush=True)
    r = requests.post(base + "@cf/black-forest-labs/flux-1-schnell", headers=hdr, timeout=120, json={"prompt": prompt, "steps": 6, "seed": seed})
    r.raise_for_status()
    return _decode(r)


def _pollinations(prompt, seed):
    from urllib.parse import quote
    r = requests.get(f"https://image.pollinations.ai/prompt/{quote(prompt[:900])}", params={"width": 768, "height": 1344, "seed": seed, "nologo": "true", "model": "flux"}, timeout=150)
    r.raise_for_status()
    return _decode(r)


def generate(prompt, seed, out, negative=NEGATIVE):
    """Make the picture and save it at `out`; returns True on success. The same prompt+seed is never generated twice."""
    key = hashlib.sha1(f"{prompt}|{seed}|{negative}".encode()).hexdigest()[:16]
    CACHE.mkdir(parents=True, exist_ok=True)
    cached = CACHE / f"{key}.png"
    if cached.exists():
        cached.replace(out) if False else out.write_bytes(cached.read_bytes())
        return True
    for name, fn in (("Cloudflare", _cloudflare), ("Pollinations", _pollinations)):
        for attempt in range(2):
            try:
                im = fn(prompt, seed, negative) if fn is _cloudflare else fn(prompt, seed)
                if im.width < 256:
                    raise ValueError("picture too small")
                im.save(cached)
                out.write_bytes(cached.read_bytes())
                return True
            except Exception as e:
                print(f"      {name} picture failed ({str(e)[:140]})", flush=True)
                time.sleep(3 + 4 * attempt)
    return False


BACK_STYLE = ("masterpiece, best quality, richly detailed painted illustration of an EMPTY place, cinematic moody lighting, warm practical lights and deep shadows, "
              "dramatic colour, soft depth of field, atmospheric, game-background art, vertical 9:16 composition, the floor or ground visible in the lower third, "
              "eye-level camera, absolutely no people, no characters, no animals, no text, no letters, no watermark")
BACK_NEG = NEGATIVE + ", person, people, man, woman, character, face, animal, cat, dog, hands"


def backdrop_prompt(script, sc):
    src = sc.get("_src") or {}
    setting = src.get("visual") or f"{STAGE.get(src.get('stage'), 'a place')}"
    return f"{BACK_STYLE}. {setting}. {WORLD.get(src.get('world'), 'daylight')}. Mood: {sc.get('tone', 'calm')}."


def backdrop(path, sc, u, D):
    """the generated background with a slow push-in; the characters move over it"""
    im = _load(path)
    p = _ease(max(0.0, min(1.0, u / max(D, 0.1))))
    z = 1.0 + 0.05 * p
    cw, ch = im.width / z, im.height / z
    x0, y0 = (im.width - cw) / 2, (im.height - ch) / 2
    return im.resize((W, H), Image.BILINEAR, box=(x0, y0, x0 + cw, y0 + ch))


def prepare(script, scenes, outdir, mode="anime"):
    """Generates every scene's picture; sets sc['_art'] to the file path (or None: that scene is drawn by the code renderer)."""
    outdir.mkdir(parents=True, exist_ok=True)
    seed = _seed(script)
    made = 0
    for i, sc in enumerate(scenes):
        path = outdir / f"scene_{i:02}.png"
        ok = generate(backdrop_prompt(script, sc) if mode == "backdrop" else scene_prompt(script, sc), seed + i, path, BACK_NEG if mode == "backdrop" else NEGATIVE)
        sc["_art"] = str(path) if ok else None
        made += ok
    print(f"      anime pictures: {made}/{len(scenes)}", flush=True)
    return made


@lru_cache(maxsize=24)
def _load(path):
    im = Image.open(path).convert("RGB")
    k = H * 1.25 / im.height                                 # headroom for the camera to move inside the picture
    im = im.resize((max(W, int(im.width * k)), int(im.height * k)), Image.LANCZOS)
    return im.filter(ImageFilter.UnsharpMask(radius=2, percent=60, threshold=3))


def _ease(x):
    return x * x * (3 - 2 * x)


def kenburns(sc, u, D):
    """The still picture, alive: a push in, a pull back or a slow pan chosen by the scene's camera, plus a faint breathing drift."""
    im = _load(sc["_art"])
    cam = (sc.get("_src") or {}).get("camera") or "hold"
    p = _ease(max(0.0, min(1.0, u / max(D, 0.1))))
    z0, z1 = {"push_in": (1.0, 1.22), "pull_back": (1.22, 1.0), "hold": (1.06, 1.12)}.get(cam, (1.04, 1.14))
    z = z0 + (z1 - z0) * p + 0.006 * math.sin(u * 1.3)
    fx = {"pan_right": 0.3 + 0.4 * p, "pan_left": 0.7 - 0.4 * p}.get(cam, 0.5 + 0.03 * math.sin(u * 0.7))
    fy = 0.5 + 0.02 * math.sin(u * 0.9 + 1)
    cw, ch = W / z * (im.height / H) / 1.25 * 1.25, H / z * (im.height / H) / 1.25 * 1.25
    cw, ch = min(cw, im.width), min(ch, im.height)
    x0 = (im.width - cw) * fx
    y0 = (im.height - ch) * fy
    return im.resize((W, H), Image.BILINEAR, box=(x0, y0, x0 + cw, y0 + ch))
